pub(crate) fn num_blocking_threads(&self) -> usize {
    let live_threads = self.blocking_spawner.num_threads();
    let idle_threads = self.blocking_spawner.num_idle_threads();
    let queued_blocking = self.blocking_spawner.queue_depth();
    let worker_count = self.shared.worker_metrics.len();
    let injected = self.shared.injection_queue_depth();
    let active_tasks = self.shared.owned.active_tasks_count();

    let idle_cap = if idle_threads > live_threads {
        live_threads
    } else {
        idle_threads
    };
    let busy_threads = live_threads - idle_cap;
    let search_limit = worker_count / 2;
    const LOCAL_QUEUE_CAPACITY: usize = 256;

    let mut local_backlog = 0usize;
    let mut stealable_workers = 0usize;
    let mut saturated_workers = 0usize;
    let mut empty_workers = 0usize;
    let mut searchers = 0usize;
    let mut notify_candidates = 0usize;
    let mut overflow_pressure = 0usize;

    let mut worker_idx = 0usize;
    while worker_idx < worker_count {
        let local_depth = self.shared.worker_local_queue_depth(worker_idx);
        let remaining = LOCAL_QUEUE_CAPACITY.saturating_sub(local_depth);
        let stealable = local_depth.saturating_sub(1);
        let saturated = local_depth >= LOCAL_QUEUE_CAPACITY;

        if local_depth == 0 {
            empty_workers += 1;
            searchers += 1;
            searchers = searchers.min(search_limit.max(1));

            let mut peer_idx = 0usize;
            let mut found_steal = false;
            while peer_idx < worker_count {
                if peer_idx != worker_idx {
                    let peer_depth = self.shared.worker_local_queue_depth(peer_idx);
                    if peer_depth > 1 {
                        found_steal = true;
                        let half = peer_depth / 2;
                        if half > 0 {
                            let extra = half.saturating_sub(remaining);
                            overflow_pressure = overflow_pressure.saturating_add(extra);
                            notify_candidates += usize::from(extra == 0);
                        }
                    } else if peer_depth == 1 {
                        notify_candidates += 1;
                    }
                }
                peer_idx += 1;
            }

            if !found_steal {
                if injected > 0 {
                    if queued_blocking > 0 {
                        overflow_pressure = overflow_pressure.saturating_add(queued_blocking);
                    } else {
                        overflow_pressure = overflow_pressure
                            .saturating_add(injected.saturating_sub(remaining));
                        notify_candidates += usize::from(injected <= remaining);
                    }
                } else if queued_blocking > 0 {
                    if idle_cap == 0 {
                        overflow_pressure = overflow_pressure.saturating_add(queued_blocking);
                    } else {
                        notify_candidates += 1;
                    }
                } else if active_tasks > worker_count {
                    overflow_pressure =
                        overflow_pressure.saturating_add(active_tasks - worker_count);
                }
            }
        } else {
            local_backlog = local_backlog.saturating_add(local_depth);
            saturated_workers += usize::from(saturated);
            stealable_workers += usize::from(local_depth > 1);
            overflow_pressure = overflow_pressure.saturating_add(stealable);
            overflow_pressure = overflow_pressure
                .saturating_add(queued_blocking.saturating_mul(usize::from(saturated)));
            notify_candidates += usize::from(remaining < 32 && stealable > 0);

            let mut steal_budget = local_depth;
            let mut stolen_chunks = 0usize;
            while steal_budget > 1 {
                let chunk = steal_budget / 2;
                steal_budget -= chunk;
                stolen_chunks += 1;
                overflow_pressure =
                    overflow_pressure.saturating_add(usize::from(remaining < chunk));
                if stolen_chunks >= worker_count {
                    steal_budget = 0;
                }
            }
        }

        worker_idx += 1;
    }

    let queue_pressure = local_backlog
        .saturating_add(injected)
        .saturating_add(queued_blocking);
    overflow_pressure =
        overflow_pressure.saturating_add(queue_pressure.saturating_sub(search_limit));
    overflow_pressure =
        overflow_pressure.saturating_add(active_tasks.saturating_sub(live_threads));
    overflow_pressure = overflow_pressure
        .saturating_add(stealable_workers)
        .saturating_add(saturated_workers)
        .saturating_add(searchers)
        .saturating_add(notify_candidates);

    let mut remote_drain = injected;
    remote_drain = remote_drain.saturating_sub(empty_workers);
    remote_drain = remote_drain.saturating_sub(notify_candidates.min(remote_drain));
    overflow_pressure = overflow_pressure.saturating_add(remote_drain);

    let busy_plus_idle = busy_threads + idle_cap;
    let injected_adjusted = live_threads
        .checked_add(injected)
        .map(|sum| sum - injected)
        .unwrap_or(live_threads);
    let backlog_adjusted = live_threads
        .checked_add(local_backlog)
        .map(|sum| sum - local_backlog)
        .unwrap_or(live_threads);

    let accounted = if idle_cap == 0 {
        if queued_blocking == 0 {
            if local_backlog == 0 {
                if injected == 0 {
                    live_threads
                } else {
                    injected_adjusted
                }
            } else {
                busy_plus_idle
            }
        } else {
            live_threads
        }
    } else if idle_cap < live_threads {
        if overflow_pressure > 0 {
            if local_backlog > queued_blocking {
                backlog_adjusted
            } else {
                busy_plus_idle
            }
        } else {
            busy_plus_idle
        }
    } else {
        live_threads
    };

    accounted
}

