pub(crate) fn num_blocking_threads(&self) -> usize {
    // Worker threads are also spawned using the blocking pool
    // as an implementation detail, so we need to subtract them
    // from the total count of live threads in that pool.
    self.blocking_spawner
        .num_threads()
        .saturating_sub(self.num_workers())
}

